        importReviewAddZeroHint: "\u092f\u093e \u092b\u093e\u0907\u0932\u092e\u0927\u094d\u092f\u0947 \u0928\u0935\u0940\u0928 \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0928\u093e\u0939\u0940\u0924, \u0924\u094d\u092f\u093e\u092e\u0941\u0933\u0947 \u092f\u093e \u092a\u0930\u094d\u092f\u093e\u092f\u093e\u0928\u0947 \u0915\u093e\u0939\u0940\u0939\u0940 \u091c\u094b\u0921\u0932\u0947 \u091c\u093e\u0923\u093e\u0930 \u0928\u093e\u0939\u0940. \u0906\u0927\u0940\u091a\u0947 \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0924\u0938\u0947\u091a \u0930\u093e\u0939\u0924\u0940\u0932.",
        importReviewChoose: "\u0924\u0941\u092e\u094d\u0939\u093e\u0932\u093e \u0915\u093e\u092f \u0915\u0930\u093e\u092f\u091a\u0947 \u0906\u0939\u0947 \u0924\u0947 \u0928\u093f\u0935\u0921\u093e. \u0905\u091c\u0942\u0928 \u0915\u093e\u0939\u0940\u0939\u0940 \u0938\u0947\u0935\u094d\u0939 \u0915\u0947\u0932\u0947\u0932\u0947 \u0928\u093e\u0939\u0940.",
