        importStockSet: "\u0938\u094d\u091f\u0949\u0915 \u092b\u093e\u0907\u0932\u092e\u0927\u0940\u0932 \u092a\u094d\u0930\u092e\u093e\u0923\u093e\u0907\u0924\u0915\u093e \u0915\u0930\u093e",
        importStockHintkeep: "\u092b\u0915\u094d\u0924 \u092e\u093e\u0939\u093f\u0924\u0940 \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0908\u0932. 10 \u091a\u093e \u0938\u094d\u091f\u0949\u0915 10 \u0930\u093e\u0939\u0940\u0932. \u0928\u0935\u0940\u0928 \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f\u091a\u093e \u0938\u0941\u0930\u0941\u0935\u093e\u0924\u0940\u091a\u093e \u0938\u094d\u091f\u0949\u0915 \u092b\u093e\u0907\u0932\u092e\u0927\u0942\u0928 \u092f\u0947\u0908\u0932.",
        importStockHintadd: "\u0909\u0926\u093e\u0939\u0930\u0923: \u0906\u0927\u0940\u091a\u0947 10 + \u092b\u093e\u0907\u0932\u092e\u0927\u0940\u0932 5 = 15. \u0928\u0935\u0940\u0928 \u092e\u093e\u0932 \u0906\u0932\u094d\u092f\u093e\u0935\u0930 \u0928\u093f\u0935\u0921\u093e. \u092a\u0941\u0928\u094d\u0939\u093e \u0907\u092e\u094d\u092a\u094b\u0930\u094d\u091f \u0915\u0947\u0932\u094d\u092f\u093e\u0938 \u092a\u0941\u0928\u094d\u0939\u093e \u091c\u094b\u0921\u0932\u0947 \u091c\u093e\u0924\u0940\u0932.",
        importStockHintset: "\u0909\u0926\u093e\u0939\u0930\u0923: \u0906\u0927\u0940\u091a\u094d\u092f\u093e 10 \u0910\u0935\u091c\u0940 \u092b\u093e\u0907\u0932\u092e\u0927\u0940\u0932 5 \u0939\u094b\u0924\u0940\u0932. \u0924\u093e\u091c\u094d\u092f\u093e \u092e\u094b\u091c\u0923\u0940\u0938\u093e\u0920\u0940 \u0928\u093f\u0935\u0921\u093e. \u0930\u093f\u0915\u093e\u092e\u094d\u092f\u093e \u0938\u094d\u091f\u0949\u0915 \u0938\u0947\u0932\u092e\u0941\u0933\u0947 \u0938\u094d\u091f\u0949\u0915 \u092c\u0926\u0932\u0923\u093e\u0930 \u0928\u093e\u0939\u0940.",
        importMatchHelp: "\u0939\u0940 \u0928\u093e\u0935\u0947 \u0906\u0927\u0940\u091a \u0906\u0939\u0947\u0924, \u092a\u0923 \u092b\u093e\u0907\u0932\u092e\u0927\u094d\u092f\u0947 \u092c\u093e\u0930\u0915\u094b\u0921 \u0915\u093f\u0902\u0935\u093e SKU \u0928\u093e\u0939\u0940. \u0924\u094b\u091a \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0905\u0938\u0947\u0932 \u0924\u0930\u091a \u0906\u0927\u0940\u091a\u093e \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0928\u093f\u0935\u0921\u093e.",
        importMatchChoose: "\u091c\u0941\u0933\u0923\u093e\u0930\u093e \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0928\u093f\u0935\u0921\u093e",
        importMatchNew: "\u0939\u093e \u0935\u0947\u0917\u0933\u093e, \u0928\u0935\u0940\u0928 \u092a\u094d\u0930\u0949\u0921\u0915\u094d\u091f \u0906\u0939\u0947",
